src/mocks/MockERC20.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import { ERC20 } from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import { ERC20Permit } from "@openzeppelin/contracts/token/ERC20/extensions/ERC20Permit.sol";

/**
 * @title MockERC20
 * @author MSQ Team
 * @notice Mock ERC20 token for testing purposes with Permit (EIP-2612) support
 */
contract MockERC20 is ERC20, ERC20Permit {
  uint8 private _decimals;

  constructor(
    string memory name,
    string memory symbol,
    uint8 decimalsValue
  ) ERC20(name, symbol) ERC20Permit(name) {
    _decimals = decimalsValue;
  }

  /**
   * @notice Returns the number of decimals used for token amounts
   * @return The number of decimals
   */
  function decimals() public view override returns (uint8) {
    return _decimals;
  }

  /**
   * @notice Mint tokens to an address (for testing)
   * @param to Address to mint to
   * @param amount Amount to mint
   */
  function mint(address to, uint256 amount) external {
    _mint(to, amount);
  }

  /**
   * @notice Burn tokens from an address (for testing)
   * @param from Address to burn from
   * @param amount Amount to burn
   */
  function burn(address from, uint256 amount) external {
    _burn(from, amount);
  }
}

src/PaymentGatewayV1.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import { UUPSUpgradeable } from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import { OwnableUpgradeable } from "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import { ERC2771ContextUpgradeable } from "@openzeppelin/contracts-upgradeable/metatx/ERC2771ContextUpgradeable.sol";
import { ReentrancyGuardUpgradeable } from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import { ContextUpgradeable } from "@openzeppelin/contracts-upgradeable/utils/ContextUpgradeable.sol";
import { EIP712Upgradeable } from "@openzeppelin/contracts-upgradeable/utils/cryptography/EIP712Upgradeable.sol";
import { ECDSA } from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { IERC20Permit } from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Permit.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { IPaymentGateway } from "./interfaces/IPaymentGateway.sol";

/**
 * @title PaymentGatewayV1
 * @author MSQ Team
 * @notice Multi-service blockchain payment gateway supporting direct and meta-transactions
 * @dev Uses UUPS proxy pattern for upgradeability and ERC2771 for meta-transaction support
 *
 * Features:
 * - Direct payments where users pay their own gas
 * - Meta-transactions via ERC2771 trusted forwarder (gasless for users)
 * - Server signature verification for payment authorization
 * - Fee deduction to treasury
 * - Duplicate payment prevention via paymentId tracking
 * - Optional token whitelist support
 *
 * @custom:security-contact security@msq.io
 */
contract PaymentGatewayV1 is
  UUPSUpgradeable,
  OwnableUpgradeable,
  ERC2771ContextUpgradeable,
  ReentrancyGuardUpgradeable,
  EIP712Upgradeable,
  IPaymentGateway
{
  using SafeERC20 for IERC20;
  using ECDSA for bytes32;

  /// @notice EIP-712 typehash for PaymentRequest
  /// @dev keccak256("PaymentRequest(bytes32 paymentId,address tokenAddress,uint256 amount,address recipientAddress,bytes32 merchantId,uint16 feeBps,uint256 deadline)")
  bytes32 public constant PAYMENT_REQUEST_TYPEHASH =
    0x848c754d9abee961cf6368834213b2f0c6ac4d2a2eb0e525c3cfc90033e268dd;

  /// @notice EIP-712 typehash for RefundRequest
  /// @dev keccak256("RefundRequest(bytes32 originalPaymentId,address tokenAddress,uint256 amount,address payerAddress,bytes32 merchantId)")
  bytes32 public constant REFUND_REQUEST_TYPEHASH =
    0x598c2433ebfb69460ac5996ae20431ae5372d75ec981feb369353efa8899a0eb;

  /// @notice Maximum fee percentage (100% = 10000 basis points)
  uint16 public constant MAX_FEE_BPS = 10000;

  // ============ Escrow Constants ============

  /// @notice EIP-712 typehash for escrow PaymentRequest (includes escrowDuration)
  bytes32 public constant ESCROW_PAYMENT_REQUEST_TYPEHASH =
    keccak256(
      "PaymentRequest(bytes32 paymentId,address tokenAddress,uint256 amount,address recipientAddress,bytes32 merchantId,uint16 feeBps,uint256 deadline,uint256 escrowDuration)"
    );

  /// @notice EIP-712 typehash for FinalizeRequest
  bytes32 public constant FINALIZE_REQUEST_TYPEHASH = keccak256("FinalizeRequest(bytes32 paymentId)");

  /// @notice EIP-712 typehash for CancelRequest
  bytes32 public constant CANCEL_REQUEST_TYPEHASH = keccak256("CancelRequest(bytes32 paymentId)");

  /// @notice Maximum escrow duration (30 days)
  uint256 public constant MAX_ESCROW_DURATION = 2592000;

  // ============ Escrow Struct ============

  struct Escrow {
    address payer;
    address token;
    uint256 amount;
    address recipient;
    bytes32 merchantId;
    uint16 feeBps;
    uint256 escrowDeadline;
    bool finalized;
    bool cancelled;
  }

  /// @notice Mapping of payment IDs to their processed status
  mapping(bytes32 => bool) public processedPayments;

  /// @notice Mapping of payment IDs to their refunded status
  mapping(bytes32 => bool) public refundedPayments;

  /// @notice Mapping of token addresses to their supported status
  mapping(address => bool) public supportedTokens;

  /// @notice Mapping of payment IDs to their escrow data
  mapping(bytes32 => Escrow) public escrows;

  /// @notice Whether token whitelist is enforced
  bool public enforceTokenWhitelist;

  /// @notice Address of the treasury
  address public treasuryAddress;

  /// @notice Address of the server signer for payment authorization
  address public signerAddress;

  /// @custom:oz-upgrades-unsafe-allow constructor
  constructor(address trustedForwarderAddress) ERC2771ContextUpgradeable(trustedForwarderAddress) {
    _disableInitializers();
  }

  /**
   * @notice Initialize the contract
   * @param owner Address of the contract owner
   * @param treasury Address of the treasury
   * @param signer Address of the server signer for payment authorization
   */
  function initialize(address owner, address treasury, address signer) public initializer {
    __UUPSUpgradeable_init();
    __Ownable_init(owner);
    __ReentrancyGuard_init();
    __EIP712_init("SoloPayGateway", "1");

    enforceTokenWhitelist = false;
    _setTreasury(treasury);
    _setSigner(signer);
  }

  /**
   * @notice Internal function to set treasury address
   * @dev Emits TreasuryChanged event
   * @param newTreasuryAddress The new treasury address
   */
  function _setTreasury(address newTreasuryAddress) internal {
    require(newTreasuryAddress != address(0), "PG: invalid treasury");
    address oldTreasuryAddress = treasuryAddress;
    treasuryAddress = newTreasuryAddress;
    emit TreasuryChanged(oldTreasuryAddress, newTreasuryAddress);
  }

  /**
   * @notice Set the treasury address
   * @dev Only callable by owner
   * @param newTreasuryAddress The new treasury address
   */
  function setTreasury(address newTreasuryAddress) external onlyOwner {
    _setTreasury(newTreasuryAddress);
  }

  /**
   * @notice Internal function to set server signer address
   * @dev Emits SignerChanged event
   * @param newSigner The new server signer address
   */
  function _setSigner(address newSigner) internal {
    require(newSigner != address(0), "PG: invalid signer");
    address oldSigner = signerAddress;
    signerAddress = newSigner;
    emit SignerChanged(oldSigner, newSigner);
  }

  /**
   * @notice Set the server signer address
   * @dev Only callable by owner
   * @param newSigner The new server signer address
   */
  function setSigner(address newSigner) external onlyOwner {
    _setSigner(newSigner);
  }

  /**
   * @notice Process a payment with server signature verification
   * @dev Transfers ERC20 tokens from the payer: fee to treasury, rest to recipient
   *      Uses _msgSender() to support both direct calls and meta-transactions
   *      Supports ERC20 Permit for gasless token approval
   * @param paymentId Unique identifier for this payment (should be hash of order ID)
   * @param tokenAddress Address of the ERC20 token to transfer
   * @param amount Amount to transfer (in token's smallest unit)
   * @param recipientAddress Address to receive the payment (merchant's wallet)
   * @param merchantId Merchant identifier (from server signature)
   * @param feeBps Fee percentage in basis points (from server signature)
   * @param deadline Expiration timestamp for the server signature
   * @param serverSignature Server's EIP-712 signature
   * @param permit Permit signature for gasless token approval (deadline=0 to skip)
   */
  function pay(
    bytes32 paymentId,
    address tokenAddress,
    uint256 amount,
    address recipientAddress,
    bytes32 merchantId,
    uint16 feeBps,
    uint256 deadline,
    bytes calldata serverSignature,
    IPaymentGateway.PermitSignature calldata permit
  ) external virtual nonReentrant {
    address payerAddress = _msgSender();

    // Process permit if deadline > 0 (try/catch to prevent frontrunning DoS)
    if (permit.deadline > 0) {
      try
        IERC20Permit(tokenAddress).permit(
          payerAddress,
          address(this),
          amount,
          permit.deadline,
          permit.v,
          permit.r,
          permit.s
        )
      {} catch {}
    }

    _processPayment(
      paymentId,
      tokenAddress,
      amount,
      recipientAddress,
      merchantId,
      feeBps,
      deadline,
      serverSignature,
      payerAddress
    );
  }

  /**
   * @notice Internal function to verify server signature
   * @param paymentId Payment identifier
   * @param tokenAddress Token address
   * @param amount Payment amount
   * @param recipientAddress Recipient address
   * @param merchantId Merchant identifier
   * @param feeBps Fee in basis points
   * @param deadline Expiration timestamp for the signature
   * @param signature Server signature
   * @return True if signature is valid
   */
  function _verifyServerSignature(
    bytes32 paymentId,
    address tokenAddress,
    uint256 amount,
    address recipientAddress,
    bytes32 merchantId,
    uint16 feeBps,
    uint256 deadline,
    bytes calldata signature
  ) internal view returns (bool) {
    bytes32 structHash = keccak256(
      abi.encode(
        PAYMENT_REQUEST_TYPEHASH,
        paymentId,
        tokenAddress,
        amount,
        recipientAddress,
        merchantId,
        feeBps,
        deadline
      )
    );

    bytes32 hash = _hashTypedDataV4(structHash);
    address recoveredSigner = hash.recover(signature);

    return recoveredSigner == signerAddress;
  }

  /**
   * @notice Internal function to validate payment inputs
   * @param paymentId Unique payment identifier
   * @param tokenAddress Token address
   * @param amount Payment amount
   * @param recipientAddress Recipient address
   * @param feeBps Fee in basis points
   * @param deadline Expiration timestamp
   */
  function _validatePayment(
    bytes32 paymentId,
    address tokenAddress,
    uint256 amount,
    address recipientAddress,
    uint16 feeBps,
    uint256 deadline
  ) internal view {
    require(block.timestamp <= deadline, "PG: expired");
    require(treasuryAddress != address(0), "PG: treasury not set");
    require(signerAddress != address(0), "PG: signer not set");
    require(!processedPayments[paymentId], "PG: already processed");
    require(amount > 0, "PG: amount must be > 0");
    require(tokenAddress != address(0), "PG: invalid token");
    require(recipientAddress != address(0), "PG: invalid recipient");
    require(feeBps <= MAX_FEE_BPS, "PG: fee too high");
  }

  /**
   * @notice Internal function to process payment
   * @dev Validates inputs, verifies signature, calculates fee, transfers tokens, emits event
   * @param paymentId Unique payment identifier
   * @param tokenAddress Token address
   * @param amount Payment amount
   * @param recipientAddress Recipient address (merchant's wallet)
   * @param merchantId Merchant identifier
   * @param feeBps Fee in basis points (from server signature)
   * @param deadline Expiration timestamp for the server signature
   * @param serverSignature Server signature
   * @param payerAddress Address of the payer
   */
  function _processPayment(
    bytes32 paymentId,
    address tokenAddress,
    uint256 amount,
    address recipientAddress,
    bytes32 merchantId,
    uint16 feeBps,
    uint256 deadline,
    bytes calldata serverSignature,
    address payerAddress
  ) internal {
    _validatePayment(paymentId, tokenAddress, amount, recipientAddress, feeBps, deadline);

    // Verify server signature
    require(
      _verifyServerSignature(
        paymentId,
        tokenAddress,
        amount,
        recipientAddress,
        merchantId,
        feeBps,
        deadline,
        serverSignature
      ),
      "PG: invalid signature"
    );

    // Check token whitelist if enforced
    if (enforceTokenWhitelist) {
      require(supportedTokens[tokenAddress], "PG: token not supported");
    }

    // Calculate fee
    uint256 feeAmount = (amount * feeBps) / MAX_FEE_BPS;
    uint256 recipientAmount = amount - feeAmount;

    // Mark as processed before transfer (reentrancy protection)
    processedPayments[paymentId] = true;

    // Transfer fee to treasury (if any)
    if (feeAmount > 0) {
      IERC20(tokenAddress).safeTransferFrom(payerAddress, treasuryAddress, feeAmount);
    }

    // Transfer remaining amount to recipient
    IERC20(tokenAddress).safeTransferFrom(payerAddress, recipientAddress, recipientAmount);

    // Emit event
    emit PaymentCompleted(
      paymentId,
      merchantId,
      payerAddress,
      recipientAddress,
      tokenAddress,
      amount,
      feeAmount,
      block.timestamp
    );
  }

  /**
   * @notice Set whether a token is supported
   * @dev Only callable by owner
   * @param tokenAddress The token address
   * @param supported Whether the token should be supported
   */
  function setSupportedToken(address tokenAddress, bool supported) external onlyOwner {
    require(tokenAddress != address(0), "PG: invalid token");
    supportedTokens[tokenAddress] = supported;
    emit TokenSupportChanged(tokenAddress, supported);
  }

  /**
   * @notice Set whether token whitelist is enforced
   * @dev Only callable by owner
   * @param enforce Whether to enforce the whitelist
   */
  function setEnforceTokenWhitelist(bool enforce) external onlyOwner {
    enforceTokenWhitelist = enforce;
  }

  /**
   * @notice Batch set supported tokens
   * @dev Only callable by owner, useful for initial setup
   * @param tokenAddresses Array of token addresses
   * @param supported Array of support statuses
   */
  function batchSetSupportedTokens(
    address[] calldata tokenAddresses,
    bool[] calldata supported
  ) external onlyOwner {
    require(tokenAddresses.length == supported.length, "PG: length mismatch");

    for (uint256 i = 0; i < tokenAddresses.length; ++i) {
      require(tokenAddresses[i] != address(0), "PG: invalid token");
      supportedTokens[tokenAddresses[i]] = supported[i];
      emit TokenSupportChanged(tokenAddresses[i], supported[i]);
    }
  }

  // ============ Refund Functions ============

  /**
   * @notice Internal function to validate refund inputs
   * @param originalPaymentId Original payment identifier
   * @param tokenAddress Token address
   * @param amount Refund amount
   * @param payerAddress Payer address (refund recipient)
   */
  function _validateRefund(
    bytes32 originalPaymentId,
    address tokenAddress,
    uint256 amount,
    address payerAddress
  ) internal view {
    require(processedPayments[originalPaymentId], "PG: payment not found");
    require(!refundedPayments[originalPaymentId], "PG: already refunded");
    require(amount > 0, "PG: amount must be > 0");
    require(tokenAddress != address(0), "PG: invalid token");
    require(payerAddress != address(0), "PG: invalid payer");
  }

  /**
   * @notice Process a refund with server signature verification
   * @dev Transfers ERC20 tokens from the merchant (msg.sender) to the original payer
   *      Uses _msgSender() to support both direct calls and meta-transactions
   *      Supports ERC20 Permit for gasless token approval
   * @param originalPaymentId The original payment ID to refund
   * @param tokenAddress Address of the ERC20 token to refund
   * @param amount Amount to refund (in token's smallest unit)
   * @param payerAddress Address to receive the refund (original payer)
   * @param merchantId Merchant identifier (from server signature)
   * @param serverSignature Server's EIP-712 signature
   * @param permit Permit signature for gasless token approval (deadline=0 to skip)
   */
  function refund(
    bytes32 originalPaymentId,
    address tokenAddress,
    uint256 amount,
    address payerAddress,
    bytes32 merchantId,
    bytes calldata serverSignature,
    IPaymentGateway.PermitSignature calldata permit
  ) external virtual nonReentrant {
    // Get the actual sender (merchant) - supports meta-transactions
    address merchantAddress = _msgSender();

    // Process permit if deadline > 0 (try/catch to prevent frontrunning DoS)
    if (permit.deadline > 0) {
      try
        IERC20Permit(tokenAddress).permit(
          merchantAddress,
          address(this),
          amount,
          permit.deadline,
          permit.v,
          permit.r,
          permit.s
        )
      {} catch {}
    }
    // Block refunds on active escrows (use cancel instead)
    Escrow storage escrow = escrows[originalPaymentId];
    if (escrow.amount > 0 && !escrow.finalized && !escrow.cancelled) {
      revert("PG: active escrow exists, use cancel");
    }

    _validateRefund(originalPaymentId, tokenAddress, amount, payerAddress);

    // Verify server signature
    require(
      _verifyRefundSignature(
        originalPaymentId,
        tokenAddress,
        amount,
        payerAddress,
        merchantId,
        serverSignature
      ),
      "PG: invalid signature"
    );

    // Mark as refunded before transfer (reentrancy protection)
    refundedPayments[originalPaymentId] = true;

    // Transfer tokens from merchant to original payer
    IERC20(tokenAddress).safeTransferFrom(merchantAddress, payerAddress, amount);

    // Emit event
    emit RefundCompleted(
      originalPaymentId,
      merchantId,
      payerAddress,
      merchantAddress,
      tokenAddress,
      amount,
      block.timestamp
    );
  }

  /**
   * @notice Internal function to verify refund server signature
   * @param originalPaymentId Original payment identifier
   * @param tokenAddress Token address
   * @param amount Refund amount
   * @param payerAddress Payer address (refund recipient)
   * @param merchantId Merchant identifier
   * @param signature Server signature
   * @return True if signature is valid
   */
  function _verifyRefundSignature(
    bytes32 originalPaymentId,
    address tokenAddress,
    uint256 amount,
    address payerAddress,
    bytes32 merchantId,
    bytes calldata signature
  ) internal view returns (bool) {
    bytes32 structHash = keccak256(
      abi.encode(
        REFUND_REQUEST_TYPEHASH,
        originalPaymentId,
        tokenAddress,
        amount,
        payerAddress,
        merchantId
      )
    );

    bytes32 hash = _hashTypedDataV4(structHash);
    address recoveredSigner = hash.recover(signature);

    return recoveredSigner == signerAddress;
  }

  /**
   * @notice Check if a payment has been refunded
   * @param paymentId The payment ID to check
   * @return True if the payment has been refunded
   */
  function isPaymentRefunded(bytes32 paymentId) external view returns (bool) {
    return refundedPayments[paymentId];
  }

  // ============ View Functions ============

  /**
   * @notice Check if a payment ID has been used
   * @param paymentId The payment ID to check
   * @return True if the payment has been processed
   */
  function isPaymentProcessed(bytes32 paymentId) external view returns (bool) {
    return processedPayments[paymentId];
  }

  /**
   * @notice Get the trusted forwarder address
   * @return Address of the trusted forwarder
   */
  function getTrustedForwarder() external view returns (address) {
    return trustedForwarder();
  }

  /**
   * @notice Get the EIP-712 domain separator
   * @return The domain separator
   */
  function getDomainSeparator() external view returns (bytes32) {
    return _domainSeparatorV4();
  }

  // ============ ERC2771 Overrides ============

  /**
   * @dev Override _msgSender to support meta-transactions
   */
  function _msgSender()
    internal
    view
    override(ContextUpgradeable, ERC2771ContextUpgradeable)
    returns (address)
  {
    return ERC2771ContextUpgradeable._msgSender();
  }

  /**
   * @dev Override _msgData to support meta-transactions
   */
  function _msgData()
    internal
    view
    override(ContextUpgradeable, ERC2771ContextUpgradeable)
    returns (bytes calldata)
  {
    return ERC2771ContextUpgradeable._msgData();
  }

  /**
   * @dev Override _contextSuffixLength for ERC2771
   */
  function _contextSuffixLength()
    internal
    view
    override(ContextUpgradeable, ERC2771ContextUpgradeable)
    returns (uint256)
  {
    return ERC2771ContextUpgradeable._contextSuffixLength();
  }

  // ============ Escrow Pay ============

  /**
   * @notice Pay into escrow with server signature verification
   * @dev Tokens are transferred from payer to this contract (escrow).
   * @param paymentId Unique payment identifier (bytes32)
   * @param tokenAddress ERC20 token address
   * @param amount Payment amount in wei
   * @param recipientAddress Merchant's wallet address
   * @param merchantId Merchant identifier (bytes32)
   * @param feeBps Fee in basis points (0-10000)
   * @param deadline Server signature expiration timestamp
   * @param escrowDuration Escrow duration in seconds (added to block.timestamp)
   * @param serverSignature Server's EIP-712 signature (escrow typehash)
   * @param permit ERC20 Permit signature (deadline=0 to skip)
   */
  function pay(
    bytes32 paymentId,
    address tokenAddress,
    uint256 amount,
    address recipientAddress,
    bytes32 merchantId,
    uint16 feeBps,
    uint256 deadline,
    uint256 escrowDuration,
    bytes calldata serverSignature,
    IPaymentGateway.PermitSignature calldata permit
  ) external nonReentrant {
    address payerAddress = _msgSender();

    if (permit.deadline > 0) {
      try
        IERC20Permit(tokenAddress).permit(
          payerAddress,
          address(this),
          amount,
          permit.deadline,
          permit.v,
          permit.r,
          permit.s
        )
      {} catch {}
    }

    _validatePayment(paymentId, tokenAddress, amount, recipientAddress, feeBps, deadline);
    require(escrowDuration > 0, "PG: escrowDuration must be > 0");
    require(escrowDuration <= MAX_ESCROW_DURATION, "PG: escrowDuration too long");

    require(
      _verifyEscrowPaymentSignature(
        paymentId, tokenAddress, amount, recipientAddress, merchantId, feeBps, deadline, escrowDuration, serverSignature
      ),
      "PG: invalid signature"
    );

    if (enforceTokenWhitelist) {
      require(supportedTokens[tokenAddress], "PG: token not supported");
    }

    uint256 escrowDeadline = block.timestamp + escrowDuration;

    processedPayments[paymentId] = true;
    escrows[paymentId] = Escrow({
      payer: payerAddress,
      token: tokenAddress,
      amount: amount,
      recipient: recipientAddress,
      merchantId: merchantId,
      feeBps: feeBps,
      escrowDeadline: escrowDeadline,
      finalized: false,
      cancelled: false
    });

    IERC20(tokenAddress).safeTransferFrom(payerAddress, address(this), amount);

    emit PaymentEscrowed(
      paymentId, merchantId, payerAddress, recipientAddress, tokenAddress, amount, escrowDeadline, block.timestamp
    );
  }

  // ============ Finalize ============

  /**
   * @notice Finalize an escrowed payment - release funds to merchant
   * @dev Only callable before escrowDeadline. Requires server signature.
   * @param paymentId The escrowed payment ID
   * @param serverSignature Server's EIP-712 FinalizeRequest signature
   */
  function finalize(bytes32 paymentId, bytes calldata serverSignature) external nonReentrant {
    Escrow storage escrow = escrows[paymentId];
    require(escrow.amount > 0, "PG: escrow not found");
    require(!escrow.finalized, "PG: already finalized");
    require(!escrow.cancelled, "PG: already cancelled");
    require(block.timestamp <= escrow.escrowDeadline, "PG: escrow expired");

    require(_verifyFinalizeSignature(paymentId, serverSignature), "PG: invalid signature");

    escrow.finalized = true;

    uint256 feeAmount = (escrow.amount * escrow.feeBps) / MAX_FEE_BPS;
    uint256 recipientAmount = escrow.amount - feeAmount;

    if (feeAmount > 0) {
      IERC20(escrow.token).safeTransfer(treasuryAddress, feeAmount);
    }
    IERC20(escrow.token).safeTransfer(escrow.recipient, recipientAmount);

    emit PaymentFinalized(
      paymentId, escrow.merchantId, escrow.recipient, escrow.token, escrow.amount, feeAmount, block.timestamp
    );
  }

  // ============ Cancel ============

  /**
   * @notice Cancel an escrowed payment - return full amount to buyer
   * @dev Before escrowDeadline: requires server signature.
   *      After escrowDeadline: permissionless (anyone can call).
   * @param paymentId The escrowed payment ID
   * @param serverSignature Server's EIP-712 CancelRequest signature (ignored after deadline)
   */
  function cancel(bytes32 paymentId, bytes calldata serverSignature) external nonReentrant {
    Escrow storage escrow = escrows[paymentId];
    require(escrow.amount > 0, "PG: escrow not found");
    require(!escrow.finalized, "PG: already finalized");
    require(!escrow.cancelled, "PG: already cancelled");

    if (block.timestamp <= escrow.escrowDeadline) {
      require(_verifyCancelSignature(paymentId, serverSignature), "PG: invalid signature");
    }

    escrow.cancelled = true;

    IERC20(escrow.token).safeTransfer(escrow.payer, escrow.amount);

    emit PaymentCancelled(
      paymentId, escrow.merchantId, escrow.payer, escrow.token, escrow.amount, block.timestamp
    );
  }

  // ============ Escrow Signature Verification ============

  function _verifyEscrowPaymentSignature(
    bytes32 paymentId,
    address tokenAddress,
    uint256 amount,
    address recipientAddress,
    bytes32 merchantId,
    uint16 feeBps,
    uint256 deadline,
    uint256 escrowDuration,
    bytes calldata signature
  ) internal view returns (bool) {
    bytes32 structHash = keccak256(
      abi.encode(
        ESCROW_PAYMENT_REQUEST_TYPEHASH,
        paymentId, tokenAddress, amount, recipientAddress, merchantId, feeBps, deadline, escrowDuration
      )
    );
    bytes32 hash = _hashTypedDataV4(structHash);
    address recoveredSigner = hash.recover(signature);
    return recoveredSigner == signerAddress;
  }

  function _verifyFinalizeSignature(bytes32 paymentId, bytes calldata signature) internal view returns (bool) {
    bytes32 structHash = keccak256(abi.encode(FINALIZE_REQUEST_TYPEHASH, paymentId));
    bytes32 hash = _hashTypedDataV4(structHash);
    address recoveredSigner = hash.recover(signature);
    return recoveredSigner == signerAddress;
  }

  function _verifyCancelSignature(bytes32 paymentId, bytes calldata signature) internal view returns (bool) {
    bytes32 structHash = keccak256(abi.encode(CANCEL_REQUEST_TYPEHASH, paymentId));
    bytes32 hash = _hashTypedDataV4(structHash);
    address recoveredSigner = hash.recover(signature);
    return recoveredSigner == signerAddress;
  }

  // ============ Escrow View Functions ============

  /**
   * @notice Get full escrow data for a payment
   * @param paymentId The payment ID
   * @return The Escrow struct
   */
  function getEscrow(bytes32 paymentId) external view returns (Escrow memory) {
    return escrows[paymentId];
  }

  // ============ UUPS Override ============

  /**
   * @dev Authorize contract upgrade (only owner)
   */
  function _authorizeUpgrade(address newImplementation) internal override onlyOwner {}
}

